const mon=i=>{const e=[0,0,0,0];e[i]=1;return new Map([[e.join(","),1n]])};
const zero=new Map();
const negate=m=>new Map([...m].map(([k,v])=>[k,-v]));
function plus(...polys){const out=new Map();for(const m of polys)for(const [k,v] of m){const w=(out.get(k)||0n)+v;if(w)out.set(k,w);else out.delete(k)}return out}
